package com.vandorlabs.neoforge.ramp;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;

/** Actual stationary world/Item ownership of prepared belt moves; no public registrations. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeRampBeltWorldChecks {
    private static int checks,readTicks;private static ServerLevel reading,writing;private static int writeTicks;private static final UUID SAVED=new UUID(0x2911,0xb317);
    private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Belt world: "+why);}
    private static void run(ServerLevel world){
        var base=new BlockPos(28128,100,28128);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.getChunkAt(base.offset(x*16,0,z*16));for(var p:BlockPos.betweenClosed(base.offset(-3,-5,-3),base.offset(4,5,4)))world.setBlock(p,Blocks.AIR.defaultBlockState(),18);
        var spec=new NativeRampFootprint.Spec(base.east(5),Direction.SOUTH,100,base.getZ(),2,0,1,0,-2,4,false,0,false,false,0,false,false,List.of(new NativeRampGeometry.Origin(base,List.of(new AABB(0,0,0,1,1,1))),new NativeRampGeometry.Origin(base.south(),List.of(new AABB(0,0,0,1,1,1)))));
        var item=new ItemEntity(world,base.getX()+.5,101,base.getZ()+.5,new ItemStack(Items.STONE));double top=NativeRampBeltTargets.support(NativeRampBeltGeometry.surfaces(spec,false,0),item.getBoundingBox());item.setPos(item.getX(),top,item.getZ());item.setDeltaMovement(.125,0,-.125);need(world.addFreshEntity(item),"real item added");var alias=new ItemEntity(world,0,0,0,new ItemStack(Items.STONE));alias.setId(item.getId());need(alias.equals(item)&&!NativeRampBeltRiders.sameActors(List.of(alias),List.of(item)),"reused numeric entity ID cannot alias exact rider identity");var initial=item.position();var state=new NativeRampBeltRiders.State(UUID.randomUUID());
        var prepared=NativeRampBeltRiders.prepare(world,spec,false,state,0,1,0);need(prepared!=null&&prepared.size()==1&&prepared.ready(),"actual item prepared");need(item.position().equals(initial)&&state.retainedEntries()==0,"prepare changes neither item nor history");item.setDeltaMovement(.25,0,0);need(!prepared.commit(null)&&item.position().equals(initial),"changed velocity rejects complete plan");item.setDeltaMovement(.125,0,-.125);
        var admission=NativeRampBeltRiders.prepare(world,spec,false,state,0,1,0);var late=new ItemEntity(world,initial.x,initial.y,initial.z,new ItemStack(Items.STONE));late.setDeltaMovement(Vec3.ZERO);need(world.addFreshEntity(late)&&!admission.recheck()&&item.position().equals(initial),"new actor after preflight refuses complete plan without partial item movement");late.discard();
        var plan=NativeRampBeltRiders.prepare(world,spec,false,state,0,1,0);need(plan!=null&&plan.recheck()&&plan.commit(null),"actual world clearance and commit");need(item.getDeltaMovement().equals(Vec3.ZERO)&&item.onGround()&&!item.noPhysics&&item.fallDistance==0&&state.retainedEntries()==1,"item transport resets velocity/fall and records weak history");need(!plan.commit(null),"single use");double distance=plan.nextDistance();var position=item.position();var duplicate=NativeRampBeltRiders.prepare(world,spec,false,state,distance,1,0);need(duplicate!=null&&duplicate.size()==0&&duplicate.nextDistance()==distance&&duplicate.commit(null)&&item.position().equals(position),"same tick never advances belt twice");
        ((net.minecraft.world.level.storage.ServerLevelData)world.getLevelData()).setGameTime(world.getGameTime()+200);item.noPhysics=true;item.setDeltaMovement(0,.2,0);item.setPos(position.x+.1,position.y+.05,position.z);var drift=item.position();var anchored=NativeRampBeltRiders.prepare(world,spec,false,state,distance,1,0);need(anchored!=null&&anchored.size()==1&&item.position().equals(drift)&&item.noPhysics,"known-history high-upward/noClip item anchor remains deferred");need(anchored.recheck()&&anchored.commit(null)&&!item.noPhysics&&item.getDeltaMovement().equals(Vec3.ZERO),"exceptional item committed through real transport");need(Math.abs(anchored.nextDistance()-distance)<.1,"200 stalled ticks advance one step only");
        var reset=NativeRampBeltRiders.prepareReset(world,spec,false,state,anchored.nextDistance(),1,0);need(reset!=null&&reset.size()==1&&reset.recheck(),"reset preflights supported real item");item.setDeltaMovement(.125,0,-.125);need(!reset.commit(null),"reset actor change refuses before retirement");reset=NativeRampBeltRiders.prepareReset(world,spec,false,state,anchored.nextDistance(),1,0);need(reset!=null&&reset.commit(null)&&item.getY()==101&&item.getDeltaMovement().equals(new Vec3(.125,0,-.125))&&state.retainedEntries()==0,"reset returns to original elevation preserving ordinary momentum and retires history");
        var old=NativeRampBeltRiders.prepare(world,spec,false,state,anchored.nextDistance(),1,0);state.reset();need(!old.ready()&&state.retainedEntries()==0,"operation reset invalidates plan/history");var before=item.position();var worker=java.util.concurrent.CompletableFuture.supplyAsync(()->{try{NativeRampBeltRiders.prepare(world,spec,false,state,0,1,0);return false;}catch(IllegalStateException expected){return true;}}).join();need(worker&&item.position().equals(before),"worker refuses before world discovery");
        need(java.util.concurrent.CompletableFuture.supplyAsync(()->{try{state.reset();return false;}catch(IllegalStateException expected){return true;}}).join(),"worker cannot reset an installed operation state");
        NativeRampBeltRiders.clearWorld(world);need(state.retainedEntries()==0,"world unload clears state");item.discard();
        var vertical=new NativeRampFootprint.Spec(spec.root(),Direction.SOUTH,100,100,2,0,1,0,-2,4,false,0,false,false,0,true,false,List.of(new NativeRampGeometry.Origin(base,List.of(new AABB(0,0,0,1,1,1))),new NativeRampGeometry.Origin(base.above(),List.of(new AABB(0,0,0,1,1,1)))));
        var surface=NativeRampBeltGeometry.surfaces(vertical,false,0).getFirst();var upright=new ItemEntity(world,(surface.minX+surface.maxX)*.5,surface.maxY,(surface.minZ+surface.maxZ)*.5,new ItemStack(Items.STONE));upright.setDeltaMovement(.125,0,-.125);need(world.addFreshEntity(upright),"actual vertical belt rider installed");var verticalState=new NativeRampBeltRiders.State(UUID.randomUUID());var verticalPlan=NativeRampBeltRiders.prepare(world,vertical,false,verticalState,0,1,0);need(verticalPlan!=null&&verticalPlan.size()==1&&verticalPlan.recheck()&&verticalPlan.commit(null),"vertical real rider commit");need(upright.getDeltaMovement().equals(new Vec3(.125,0,-.125))&&verticalState.retainedEntries()==0,"vertical belt uses ordinary momentum without horizontal item tracking history");var verticalReset=NativeRampBeltRiders.prepareReset(world,vertical,false,verticalState,verticalPlan.nextDistance(),1,0);need(verticalReset!=null&&verticalReset.recheck()&&verticalReset.commit(null),"vertical original-geometry reset commits");upright.discard();
        world.setChunkForced(base.getX()>>4,base.getZ()>>4,true);
        var saved=new ItemEntity(world,base.getX()+.5,101,base.getZ()+.5,new ItemStack(Items.STONE,3));saved.setUUID(SAVED);saved.setNoGravity(true);saved.setNeverPickUp();saved.setDeltaMovement(Vec3.ZERO);saved.getItem().set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(payload()));need(world.addFreshEntity(saved),"independent persisted real item owner installed");
    }
    private static net.minecraft.nbt.CompoundTag payload(){var tag=new net.minecraft.nbt.CompoundTag();tag.putString("OpaqueBeltFixture","retained");tag.putLong("PreviousRelease",291101);return tag;}
    @SubscribeEvent public static void read(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){if(writing!=null){if(++writeTicks<20)return;writing=null;System.out.println("[vandorlabs][ramp-belt-world] PASS checks="+checks);event.getServer().halt(false);return;}if(reading==null)return;var entity=reading.getEntity(SAVED);if(entity==null){need(++readTicks<200,"saved actual Item entity eventually loads");return;}try{need(entity instanceof ItemEntity,"saved UUID retains exact real Item entity type");var item=(ItemEntity)entity;need(item.getItem().is(Items.STONE)&&item.getItem().getCount()==3&&item.getItem().get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag().equals(payload()),"restart retains complete item payload and quantity");var fresh=new NativeRampBeltRiders.State(new UUID(0,2911));need(fresh.retainedEntries()==0,"restart never resurrects anchoring history");need(item.getY()==101&&item.getDeltaMovement().equals(Vec3.ZERO)&&!item.noPhysics,"saved authoritative item state stable after process restart");System.out.println("[vandorlabs][ramp-belt-world] restart PASS checks="+checks);}finally{reading=null;event.getServer().halt(false);}}
    @SubscribeEvent public static void started(ServerStartedEvent event){var phase=System.getProperty("vandorlabs.transmitterPhase");if(!"ramp-belt-world".equals(phase)&&!"ramp-belt-world-read".equals(phase))return;if(phase.endsWith("-read")){reading=event.getServer().overworld();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)reading.getChunkAt(new BlockPos(28128+x*16,100,28128+z*16));System.out.println("actual server PID="+ProcessHandle.current().pid());return;}System.out.println("actual server PID="+ProcessHandle.current().pid());try{run(event.getServer().overworld());writing=event.getServer().overworld();}catch(RuntimeException|Error failure){event.getServer().halt(false);throw failure;}}
}
